local bxor = (bit32 and bit32.bxor) or function(a, b)
    local r, p = 0, 1
    while a > 0 or b > 0 do
        if (a % 2) ~= (b % 2) then r = r + p end
        a = math.floor(a / 2)
        b = math.floor(b / 2)
        p = p * 2
    end
    return r
end

local function b64decode(data)
    if crypt and crypt.base64decode then return crypt.base64decode(data) end
    if base64 and base64.decode then return base64.decode(data) end
    if base64_decode then return base64_decode(data) end
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map = {}
    for i = 1, #chars do map[chars:sub(i, i)] = i - 1 end
    local out, buffer, bits = {}, 0, 0
    for i = 1, #data do
        local ch = data:sub(i, i)
        if ch == "=" then break end
        local value = map[ch]
        if value ~= nil then
            buffer = buffer * 64 + value
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                out[#out + 1] = string.char(math.floor(buffer / (2 ^ bits)) % 256)
                buffer = buffer % (2 ^ bits)
            end
        end
    end
    return table.concat(out)
end

local function xorDecode(data)
    local out = table.create and table.create(#data) or {}
    local kl = #_k
    for i = 1, #data do
        out[i] = string.char(bxor(string.byte(data, i), _k[((i - 1) % kl) + 1]))
    end
    return table.concat(out)
end

local parts = table.create and table.create(#_c) or {}
for i = 1, #_c do
    local ok, decoded = pcall(b64decode, _c[i])
    if not ok or type(decoded) ~= "string" then
        error("[KFC OBF] base64 decode failed at chunk " .. i)
    end
    parts[i] = xorDecode(decoded)
end

local source = table.concat(parts)
local runner, err = loadstring(source)
if type(runner) ~= "function" then
    error("[KFC OBF] loadstring failed: " .. tostring(err))
end
runner()
